begin;

create table public.marketplace_order_settlements(
 id uuid primary key default gen_random_uuid(), payment_id uuid not null references public.marketplace_payments(id),
 allocation_id uuid not null unique references public.marketplace_payment_allocations(id), checkout_id uuid not null references public.marketplace_checkout_sessions(id),
 order_id uuid not null unique references public.marketplace_orders(id), buyer_id uuid not null references auth.users(id),
 seller_id uuid not null references public.marketplace_sellers(user_id), store_id uuid not null references public.marketplace_stores(id),
 currency text not null default 'BDAG', gross_amount numeric(20,8) not null, seller_net_amount numeric(20,8) not null,
 platform_fee_amount numeric(20,8) not null, status text not null default 'completed', confirmed_by uuid not null references auth.users(id),
 idempotency_key uuid not null, request_fingerprint text not null, confirmed_at timestamptz not null, released_at timestamptz not null,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 constraint marketplace_settlement_currency_check check(currency='BDAG'),
 constraint marketplace_settlement_amount_check check(gross_amount>0 and seller_net_amount>=0 and platform_fee_amount>=0 and gross_amount=round(gross_amount,8) and seller_net_amount=round(seller_net_amount,8) and platform_fee_amount=round(platform_fee_amount,8) and gross_amount=seller_net_amount+platform_fee_amount),
 constraint marketplace_settlement_status_check check(status='completed' and confirmed_at is not null and released_at is not null),
 constraint marketplace_settlement_buyer_check check(confirmed_by=buyer_id),
 constraint marketplace_settlement_fingerprint_check check(char_length(request_fingerprint)=64), unique(buyer_id,idempotency_key)
);

create table public.marketplace_settlement_legs(
 id uuid primary key default gen_random_uuid(), settlement_id uuid not null references public.marketplace_order_settlements(id),
 leg_key text not null, leg_type text not null, beneficiary_user_id uuid references auth.users(id),
 destination_account_id uuid not null references public.ledger_accounts(id), amount numeric(20,8) not null,
 financial_transaction_id uuid unique references public.financial_transactions(id), status text not null default 'completed',
 created_at timestamptz not null default now(), unique(settlement_id,leg_key),
 constraint marketplace_settlement_leg_type_check check(leg_type in ('seller_net','platform_fee','influencer_commission')),
 constraint marketplace_settlement_leg_amount_check check(amount>=0 and amount=round(amount,8)),
 constraint marketplace_settlement_leg_status_check check(status='completed'),
 constraint marketplace_settlement_leg_transaction_check check((amount>0 and financial_transaction_id is not null) or (amount=0 and financial_transaction_id is null)),
 constraint marketplace_settlement_leg_beneficiary_check check((leg_type='seller_net' and beneficiary_user_id is not null) or (leg_type='platform_fee' and beneficiary_user_id is null) or leg_type='influencer_commission')
);

create index marketplace_settlements_payment_idx on public.marketplace_order_settlements(payment_id);
create index marketplace_settlement_legs_settlement_idx on public.marketplace_settlement_legs(settlement_id);

drop index public.marketplace_order_events_command_unique;
create unique index marketplace_order_events_command_unique on public.marketplace_order_events(order_id,actor_id,idempotency_key,event_type) where idempotency_key is not null;

create or replace function public.ensure_marketplace_platform_account() returns uuid language plpgsql security definer set search_path=public as $$
declare v_id uuid;begin
 insert into public.ledger_accounts(owner_id,account_type,currency,balance,frozen) values(null,'platform','BDAG',0,false)
 on conflict on constraint ledger_accounts_system_unique do nothing;
 select id into strict v_id from public.ledger_accounts where owner_id is null and account_type='platform' and currency='BDAG';return v_id;
end$$;

create or replace function public.marketplace_allocation_release_guard() returns trigger language plpgsql set search_path=public as $$
begin
 if current_setting('app.marketplace_settlement',true)='on' and old.status='held' and new.status='released' and old.id=new.id and old.payment_id=new.payment_id and old.checkout_id=new.checkout_id and old.order_id=new.order_id and old.seller_id=new.seller_id and old.store_id=new.store_id and old.currency=new.currency and old.gross_amount=new.gross_amount and old.platform_fee_amount=new.platform_fee_amount and old.seller_net_amount=new.seller_net_amount and old.fee_bps=new.fee_bps and new.released_at is not null and new.refunded_at is null then return new;end if;
 raise exception using errcode='42501',message='marketplace_payment_snapshot_immutable';
end$$;
drop trigger marketplace_allocations_immutable on public.marketplace_payment_allocations;
create trigger marketplace_allocations_immutable before update or delete on public.marketplace_payment_allocations for each row execute function public.marketplace_allocation_release_guard();

create or replace function public.marketplace_order_settlement_receipt(p_settlement_id uuid,p_role text) returns jsonb language sql stable security definer set search_path=public as $$
select jsonb_build_object('settlement',jsonb_build_object('id',s.id,'status',s.status,'order_id',s.order_id,'currency',s.currency,'gross_amount',s.gross_amount,'seller_net_amount',case when p_role='seller' then s.seller_net_amount else null end,'platform_fee_amount',case when p_role='seller' then s.platform_fee_amount else null end,'confirmed_at',s.confirmed_at,'released_at',s.released_at),
 'order',jsonb_build_object('id',o.id,'status',o.status,'delivered_at',o.delivered_at),
 'shipment',jsonb_build_object('status',sh.status,'delivered_at',sh.delivered_at),
 'allocation',jsonb_build_object('status',a.status,'released_at',a.released_at),
 'seller',case when p_role='seller' then jsonb_build_object('new_bdag_balance',(select balance from public.ledger_accounts where owner_id=s.seller_id and account_type='user' and currency='BDAG')) else null end)
from public.marketplace_order_settlements s join public.marketplace_orders o on o.id=s.order_id join public.marketplace_order_shipments sh on sh.order_id=o.id join public.marketplace_payment_allocations a on a.id=s.allocation_id where s.id=p_settlement_id and p_role in ('buyer','seller');$$;

create or replace function public.confirm_marketplace_order_delivery_and_release(p_buyer_id uuid,p_order_id uuid,p_idempotency_key uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare o public.marketplace_orders;sh public.marketplace_order_shipments;p public.marketplace_payments;a public.marketplace_payment_allocations;s public.marketplace_order_settlements;
 v_fingerprint text;v_settlement uuid:=gen_random_uuid();v_escrow uuid;v_seller_account uuid;v_platform_account uuid;v_seller_tx uuid;v_platform_tx uuid;v_now timestamptz:=now();v_escrow_balance numeric;
begin
 if p_buyer_id is null or p_order_id is null or p_idempotency_key is null then raise exception using errcode='22023',message='marketplace_delivery_invalid_input';end if;
 v_fingerprint:=pg_catalog.encode(extensions.digest('marketplace_order_confirm_delivery:'||p_order_id::text,'sha256'),'hex');
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_buyer_id::text||':marketplace-delivery:'||p_idempotency_key::text,0));
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('marketplace-order-settlement:'||p_order_id::text,0));
 select * into o from public.marketplace_orders where id=p_order_id for update;
 if not found then raise exception using errcode='P0002',message='marketplace_order_not_found';end if;
 if o.buyer_id<>p_buyer_id then raise exception using errcode='42501',message='marketplace_order_not_owned';end if;
 select * into s from public.marketplace_order_settlements where buyer_id=p_buyer_id and idempotency_key=p_idempotency_key;
 if found then if s.order_id<>p_order_id or s.request_fingerprint<>v_fingerprint then raise exception using errcode='23505',message='marketplace_settlement_idempotency_conflict';end if;return public.marketplace_order_settlement_receipt(s.id,'buyer');end if;
 select * into s from public.marketplace_order_settlements where order_id=p_order_id;if found then return public.marketplace_order_settlement_receipt(s.id,'buyer');end if;
 select * into sh from public.marketplace_order_shipments where order_id=o.id for update;
 select mp.* into p from public.marketplace_payments mp join public.marketplace_checkout_sessions c on c.id=mp.checkout_id where mp.checkout_id=o.checkout_id and c.status='paid' for update of mp;
 select * into a from public.marketplace_payment_allocations where order_id=o.id for update;
 if p.id is null or p.status<>'paid' then raise exception using errcode='22023',message='marketplace_order_not_paid';end if;
 if o.status<>'shipped' then raise exception using errcode='22023',message='marketplace_order_not_shipped';end if;
 if sh.id is null or sh.status<>'shipped' then raise exception using errcode='22023',message='marketplace_shipment_not_shipped';end if;
 if a.id is null or a.status<>'held' then raise exception using errcode='22023',message='marketplace_allocation_not_held';end if;
 if a.payment_id<>p.id or a.checkout_id<>o.checkout_id or a.seller_id<>o.seller_id or a.store_id<>o.store_id or a.currency<>'BDAG' or o.currency<>'BDAG' or a.gross_amount<>o.total or a.gross_amount<>a.seller_net_amount+a.platform_fee_amount then raise exception using errcode='23514',message='marketplace_settlement_integrity_error';end if;
 v_escrow:=public.ensure_marketplace_escrow_account();v_seller_account:=public.ensure_ledger_account(o.seller_id);v_platform_account:=public.ensure_marketplace_platform_account();
 perform 1 from public.ledger_accounts where id in(v_escrow,v_seller_account,v_platform_account) order by id for update;
 select balance into v_escrow_balance from public.ledger_accounts where id=v_escrow and currency='BDAG' and not frozen;
 if v_escrow_balance is null or v_escrow_balance<a.gross_amount then raise exception using errcode='P0001',message='marketplace_escrow_insufficient_balance';end if;
 if exists(select 1 from public.ledger_accounts where id in(v_seller_account,v_platform_account) and (currency<>'BDAG' or frozen)) then raise exception using errcode='23514',message='marketplace_settlement_integrity_error';end if;
 insert into public.marketplace_order_settlements(id,payment_id,allocation_id,checkout_id,order_id,buyer_id,seller_id,store_id,gross_amount,seller_net_amount,platform_fee_amount,confirmed_by,idempotency_key,request_fingerprint,confirmed_at,released_at) values(v_settlement,p.id,a.id,o.checkout_id,o.id,o.buyer_id,o.seller_id,o.store_id,a.gross_amount,a.seller_net_amount,a.platform_fee_amount,p_buyer_id,p_idempotency_key,v_fingerprint,v_now,v_now);
 if a.seller_net_amount>0 then v_seller_tx:=gen_random_uuid();insert into public.financial_transactions(id,from_account_id,to_account_id,operation_type,amount,fee_amount,currency,status,reference_type,reference_id,idempotency_key,initiated_by) values(v_seller_tx,v_escrow,v_seller_account,'marketplace_seller_settlement',a.seller_net_amount,0,'BDAG','completed','marketplace_order',o.id::text,(v_settlement::text||':seller'),p_buyer_id);perform public.ledger_debit(v_seller_tx,v_escrow,a.seller_net_amount,'Marketplace seller settlement',jsonb_build_object('fin_txn_id',v_seller_tx,'order_id',o.id));perform public.ledger_credit(v_seller_tx,v_seller_account,a.seller_net_amount,'Marketplace seller settlement',jsonb_build_object('fin_txn_id',v_seller_tx,'order_id',o.id));end if;
 insert into public.marketplace_settlement_legs(settlement_id,leg_key,leg_type,beneficiary_user_id,destination_account_id,amount,financial_transaction_id) values(v_settlement,'seller_net','seller_net',o.seller_id,v_seller_account,a.seller_net_amount,v_seller_tx);
 if a.platform_fee_amount>0 then v_platform_tx:=gen_random_uuid();insert into public.financial_transactions(id,from_account_id,to_account_id,operation_type,amount,fee_amount,currency,status,reference_type,reference_id,idempotency_key,initiated_by) values(v_platform_tx,v_escrow,v_platform_account,'marketplace_platform_fee_settlement',a.platform_fee_amount,0,'BDAG','completed','marketplace_order',o.id::text,(v_settlement::text||':platform'),p_buyer_id);perform public.ledger_debit(v_platform_tx,v_escrow,a.platform_fee_amount,'Marketplace platform fee settlement',jsonb_build_object('fin_txn_id',v_platform_tx,'order_id',o.id));perform public.ledger_credit(v_platform_tx,v_platform_account,a.platform_fee_amount,'Marketplace platform fee settlement',jsonb_build_object('fin_txn_id',v_platform_tx,'order_id',o.id));end if;
 insert into public.marketplace_settlement_legs(settlement_id,leg_key,leg_type,beneficiary_user_id,destination_account_id,amount,financial_transaction_id) values(v_settlement,'platform_fee','platform_fee',null,v_platform_account,a.platform_fee_amount,v_platform_tx);
 perform set_config('app.marketplace_settlement','on',true);update public.marketplace_payment_allocations set status='released',released_at=v_now where id=a.id and status='held';
 update public.marketplace_orders set status='delivered',delivered_at=v_now,fulfillment_updated_at=v_now,fulfillment_version=fulfillment_version+1 where id=o.id and status='shipped';
 update public.marketplace_order_shipments set status='delivered',delivered_at=v_now where id=sh.id and status='shipped';
 insert into public.marketplace_order_events(order_id,checkout_id,buyer_id,seller_id,store_id,event_type,from_status,to_status,actor_id,actor_role,idempotency_key,metadata,created_at) values(o.id,o.checkout_id,o.buyer_id,o.seller_id,o.store_id,'delivery_confirmed','shipped','delivered',p_buyer_id,'buyer',p_idempotency_key,jsonb_build_object('settlement_id',v_settlement,'currency','BDAG'),v_now),(o.id,o.checkout_id,o.buyer_id,o.seller_id,o.store_id,'escrow_released','delivered','delivered',p_buyer_id,'buyer',p_idempotency_key,jsonb_build_object('settlement_id',v_settlement,'currency','BDAG','status','released'),v_now);
 return public.marketplace_order_settlement_receipt(v_settlement,'buyer');
end$$;

create or replace function public.marketplace_order_detail_response(p_order_id uuid,p_role text) returns jsonb language sql stable security definer set search_path=public as $$
select jsonb_build_object('order',jsonb_build_object('id',o.id,'order_number',o.order_number,'checkout_id',o.checkout_id,'checkout_reference',c.reference,'status',o.status,'currency',o.currency,'total',o.total,'created_at',o.created_at,'confirmed_at',o.confirmed_at,'processing_at',o.processing_at,'shipped_at',o.shipped_at,'delivered_at',o.delivered_at,'fulfillment_version',o.fulfillment_version),'store',jsonb_build_object('id',st.id,'name',st.name,'slug',st.slug),'payment',jsonb_build_object('status',p.status,'paid_at',p.paid_at),'allocation',case when p_role='seller' then jsonb_build_object('gross_amount',a.gross_amount,'platform_fee_amount',a.platform_fee_amount,'seller_net_amount',a.seller_net_amount,'status',a.status,'released_at',a.released_at) else null end,'settlement',case when se.id is null then null else jsonb_build_object('status',se.status,'gross_amount',se.gross_amount,'seller_net_amount',case when p_role='seller' then se.seller_net_amount else null end,'platform_fee_amount',case when p_role='seller' then se.platform_fee_amount else null end,'confirmed_at',se.confirmed_at,'released_at',se.released_at,'seller_bdag_balance',case when p_role='seller' then (select balance from public.ledger_accounts where owner_id=o.seller_id and account_type='user' and currency='BDAG') else null end) end,'shipping_address',jsonb_build_object('recipient_name',sa.recipient_name,'line1',sa.line1,'line2',sa.line2,'city',sa.city,'region',sa.region,'postal_code',sa.postal_code,'country',sa.country,'phone',sa.phone),'items',coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'product_title',i.product_title,'variant_title',i.variant_title,'sku',i.sku,'options',i.option_snapshot,'image_url',i.image_url,'unit_price',i.unit_price,'quantity',i.quantity,'line_total',i.line_total) order by i.created_at) from public.marketplace_order_items i where i.order_id=o.id),'[]'::jsonb),'shipment',(select jsonb_build_object('id',case when p_role='seller' then sh.id else null end,'status',sh.status,'carrier_name',sh.carrier_name,'service_level',sh.service_level,'tracking_number',sh.tracking_number,'tracking_url',sh.tracking_url,'seller_note',case when p_role='seller' then sh.seller_note else null end,'shipped_at',sh.shipped_at,'delivered_at',sh.delivered_at) from public.marketplace_order_shipments sh where sh.order_id=o.id),'events',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'event_type',e.event_type,'from_status',e.from_status,'to_status',e.to_status,'actor_role',e.actor_role,'created_at',e.created_at) order by e.created_at,e.id) from public.marketplace_order_events e where e.order_id=o.id),'[]'::jsonb),'escrow_protected',a.status='held') from public.marketplace_orders o join public.marketplace_checkout_sessions c on c.id=o.checkout_id join public.marketplace_stores st on st.id=o.store_id join public.marketplace_checkout_shipping_addresses sa on sa.checkout_id=o.checkout_id join public.marketplace_payments p on p.checkout_id=o.checkout_id join public.marketplace_payment_allocations a on a.order_id=o.id left join public.marketplace_order_settlements se on se.order_id=o.id where o.id=p_order_id;$$;

create or replace function public.reconcile_marketplace_settlements() returns jsonb language sql stable security definer set search_path=public as $$
select jsonb_build_object('released_without_settlement',(select count(*) from public.marketplace_payment_allocations a left join public.marketplace_order_settlements s on s.allocation_id=a.id where a.status='released' and s.id is null),'settlement_without_release',(select count(*) from public.marketplace_order_settlements s join public.marketplace_payment_allocations a on a.id=s.allocation_id where a.status<>'released'),'amount_mismatches',(select count(*) from public.marketplace_order_settlements s join public.marketplace_payment_allocations a on a.id=s.allocation_id where (s.gross_amount,s.seller_net_amount,s.platform_fee_amount)<>(a.gross_amount,a.seller_net_amount,a.platform_fee_amount)),'leg_mismatches',(select count(*) from public.marketplace_order_settlements s where s.gross_amount<>(select coalesce(sum(amount),0) from public.marketplace_settlement_legs l where l.settlement_id=s.id and l.status='completed') or 1<>(select count(*) from public.marketplace_settlement_legs l where l.settlement_id=s.id and l.leg_type='seller_net') or 1<>(select count(*) from public.marketplace_settlement_legs l where l.settlement_id=s.id and l.leg_type='platform_fee')),'transaction_mismatches',(select count(*) from public.marketplace_settlement_legs l left join public.financial_transactions f on f.id=l.financial_transaction_id where l.amount>0 and (f.id is null or f.status<>'completed' or f.amount<>l.amount)),'delivery_mismatches',(select count(*) from public.marketplace_order_settlements s join public.marketplace_orders o on o.id=s.order_id join public.marketplace_order_shipments sh on sh.order_id=o.id where o.status<>'delivered' or sh.status<>'delivered' or o.delivered_at<>sh.delivered_at),'escrow_shortfall',greatest((select coalesce(sum(gross_amount),0) from public.marketplace_payment_allocations where status='held')-(select coalesce(balance,0) from public.ledger_accounts where owner_id is null and account_type='marketplace_escrow'),0));$$;

create or replace function public.fetch_my_marketplace_sale(p_order_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare o public.marketplace_orders;begin
 if auth.uid() is null then raise exception using errcode='42501',message='marketplace_auth_required';end if;
 select * into o from public.marketplace_orders where id=p_order_id;if not found then raise exception using errcode='P0002',message='marketplace_order_not_found';end if;
 if o.seller_id<>auth.uid() then raise exception using errcode='42501',message='marketplace_order_not_owned';end if;
 if not exists(select 1 from public.marketplace_sellers where user_id=auth.uid() and status='approved') then raise exception using errcode='42501',message='marketplace_seller_not_approved';end if;
 if not exists(select 1 from public.marketplace_stores where id=o.store_id and seller_id=auth.uid() and status='active') then raise exception using errcode='42501',message='marketplace_store_inactive';end if;
 if not exists(select 1 from public.marketplace_checkout_sessions c join public.marketplace_payments p on p.checkout_id=c.id and p.status='paid' where c.id=o.checkout_id and c.status='paid') then raise exception using errcode='42501',message='marketplace_order_not_paid';end if;
 if not exists(select 1 from public.marketplace_payment_allocations a where a.order_id=o.id and a.seller_id=auth.uid() and ((o.status='delivered' and a.status='released') or (o.status<>'delivered' and a.status='held'))) then raise exception using errcode='42501',message='marketplace_order_not_fulfillable';end if;
 return public.marketplace_order_detail_response(o.id,'seller');
end$$;

create or replace function public.fetch_my_marketplace_orders(p_status text default null,p_limit integer default 20,p_before_created_at timestamptz default null,p_before_id uuid default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_limit int:=least(greatest(coalesce(p_limit,20),1),50);begin
 if auth.uid() is null then raise exception using errcode='42501',message='marketplace_auth_required';end if;if p_status is not null and p_status not in ('confirmed','processing','shipped','delivered','cancelled','refunded','partially_refunded') then raise exception using errcode='22023',message='marketplace_invalid_order_status';end if;
 return coalesce((select jsonb_agg(x.row order by x.created_at desc,x.id desc) from (select o.created_at,o.id,jsonb_build_object('id',o.id,'order_number',o.order_number,'checkout_id',o.checkout_id,'checkout_reference',c.reference,'status',o.status,'store_id',o.store_id,'store_name',st.name,'total',o.total,'currency',o.currency,'created_at',o.created_at,'confirmed_at',o.confirmed_at,'processing_at',o.processing_at,'shipped_at',o.shipped_at,'delivered_at',o.delivered_at,'first_item_title',(select i.product_title from public.marketplace_order_items i where i.order_id=o.id order by i.created_at limit 1),'first_item_image',(select i.image_url from public.marketplace_order_items i where i.order_id=o.id order by i.created_at limit 1),'distinct_lines',(select count(*) from public.marketplace_order_items i where i.order_id=o.id),'total_quantity',(select sum(i.quantity) from public.marketplace_order_items i where i.order_id=o.id),'carrier_name',sh.carrier_name,'tracking_number',sh.tracking_number,'payment_status',p.status) row from public.marketplace_orders o join public.marketplace_checkout_sessions c on c.id=o.checkout_id and c.status='paid' join public.marketplace_stores st on st.id=o.store_id join public.marketplace_payments p on p.checkout_id=o.checkout_id and p.status='paid' left join public.marketplace_order_shipments sh on sh.order_id=o.id where o.buyer_id=auth.uid() and (p_status is null or o.status=p_status) and (p_before_created_at is null or (o.created_at,o.id)<(p_before_created_at,p_before_id)) order by o.created_at desc,o.id desc limit v_limit)x),'[]'::jsonb);end$$;

create or replace function public.fetch_my_marketplace_sales(p_status text default null,p_limit integer default 20,p_before_created_at timestamptz default null,p_before_id uuid default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_limit int:=least(greatest(coalesce(p_limit,20),1),50);v_store uuid;begin
 if auth.uid() is null then raise exception using errcode='42501',message='marketplace_auth_required';end if;if not exists(select 1 from public.marketplace_sellers where user_id=auth.uid() and status='approved') then raise exception using errcode='42501',message='marketplace_seller_not_approved';end if;select id into v_store from public.marketplace_stores where seller_id=auth.uid() and status='active';if v_store is null then raise exception using errcode='42501',message='marketplace_store_inactive';end if;if p_status is not null and p_status not in ('confirmed','processing','shipped','delivered','cancelled','refunded','partially_refunded') then raise exception using errcode='22023',message='marketplace_invalid_order_status';end if;
 return coalesce((select jsonb_agg(x.row order by x.created_at desc,x.id desc) from (select o.created_at,o.id,jsonb_build_object('id',o.id,'order_number',o.order_number,'checkout_id',o.checkout_id,'checkout_reference',c.reference,'status',o.status,'store_id',o.store_id,'store_name',st.name,'total',o.total,'currency',o.currency,'created_at',o.created_at,'confirmed_at',o.confirmed_at,'processing_at',o.processing_at,'shipped_at',o.shipped_at,'delivered_at',o.delivered_at,'recipient_name',sa.recipient_name,'city',sa.city,'region',sa.region,'country',sa.country,'distinct_lines',(select count(*) from public.marketplace_order_items i where i.order_id=o.id),'total_quantity',(select sum(i.quantity) from public.marketplace_order_items i where i.order_id=o.id),'gross_amount',a.gross_amount,'platform_fee_amount',a.platform_fee_amount,'seller_net_amount',a.seller_net_amount,'allocation_status',a.status,'released_at',a.released_at,'carrier_name',sh.carrier_name,'tracking_number',sh.tracking_number) row from public.marketplace_orders o join public.marketplace_checkout_sessions c on c.id=o.checkout_id and c.status='paid' join public.marketplace_stores st on st.id=o.store_id join public.marketplace_checkout_shipping_addresses sa on sa.checkout_id=o.checkout_id join public.marketplace_payment_allocations a on a.order_id=o.id left join public.marketplace_order_shipments sh on sh.order_id=o.id where o.seller_id=auth.uid() and o.store_id=v_store and (p_status is null or o.status=p_status) and (p_before_created_at is null or (o.created_at,o.id)<(p_before_created_at,p_before_id)) order by o.created_at desc,o.id desc limit v_limit)x),'[]'::jsonb);end$$;

alter table public.marketplace_order_settlements enable row level security;alter table public.marketplace_settlement_legs enable row level security;
create trigger marketplace_settlements_updated_at before update on public.marketplace_order_settlements for each row execute function public.marketplace_set_updated_at();
create trigger marketplace_settlements_immutable before update or delete on public.marketplace_order_settlements for each row execute function public.marketplace_reject_fulfillment_audit_mutation();
create trigger marketplace_settlement_legs_immutable before update or delete on public.marketplace_settlement_legs for each row execute function public.marketplace_reject_fulfillment_audit_mutation();
revoke all on public.marketplace_order_settlements,public.marketplace_settlement_legs from public,anon,authenticated;
revoke all on function public.ensure_marketplace_platform_account(),public.marketplace_order_settlement_receipt(uuid,text),public.confirm_marketplace_order_delivery_and_release(uuid,uuid,uuid),public.reconcile_marketplace_settlements() from public,anon,authenticated;
grant execute on function public.confirm_marketplace_order_delivery_and_release(uuid,uuid,uuid),public.marketplace_order_settlement_receipt(uuid,text),public.ensure_marketplace_platform_account(),public.reconcile_marketplace_settlements() to service_role;
revoke all on function public.fetch_my_marketplace_order(uuid),public.fetch_my_marketplace_sale(uuid),public.fetch_my_marketplace_orders(text,integer,timestamptz,uuid),public.fetch_my_marketplace_sales(text,integer,timestamptz,uuid) from public,anon,authenticated;
grant execute on function public.fetch_my_marketplace_order(uuid),public.fetch_my_marketplace_sale(uuid),public.fetch_my_marketplace_orders(text,integer,timestamptz,uuid),public.fetch_my_marketplace_sales(text,integer,timestamptz,uuid) to authenticated,service_role;

commit;
